  "I manage my own learning": "मैं अपनी पढ़ाई खुद सँभालता/सँभालती हूँ",
  "Students aged 18+ can register with their own email, add school or college details and find a teacher. Inviting a guardian or supporter is optional.": "18 वर्ष या अधिक के विद्यार्थी अपने ईमेल से खाता बना सकते हैं, स्कूल या कॉलेज की जानकारी जोड़ सकते हैं और शिक्षक खोज सकते हैं। अभिभावक या मददगार को आमंत्रित करना वैकल्पिक है।",
  "Create my student profile (18+)": "अपनी विद्यार्थी प्रोफ़ाइल बनाएँ (18+)",
  "I have a guardian’s support": "मेरे साथ अभिभावक की मदद है",
