  "The student signs in with this email and opens Guardian verification to acknowledge or decline. Do not use your own email.": "विद्यार्थी इस ईमेल से प्रवेश करके अभिभावक सत्यापन में रिश्ते की पुष्टि या अस्वीकृति करेगा। अपना ईमेल न दें।",
  "Use a staff call for younger learners without email or when student sign-in is unavailable. Staff must establish the relationship acknowledgment and your adult authority.": "छोटे बच्चों के पास ईमेल न होने या विद्यार्थी का प्रवेश उपलब्ध न होने पर कर्मचारी कॉल चुनें। कर्मचारी रिश्ते की पुष्टि और वयस्क के रूप में आपके अधिकार की जाँच करेंगे।",
