  "I permit private review of these relationship details and the school report for verification. This does not grant learning-data consent.": "मैं सत्यापन के लिए इस रिश्ते और स्कूल रिपोर्ट की निजी समीक्षा की अनुमति देता/देती हूँ। इससे पढ़ाई के डेटा की सहमति नहीं मिलती।",
  "Review relationship details": "रिश्ते के विवरण की समीक्षा करें",
