  "Send for staff review": "कर्मचारी समीक्षा के लिए भेजें",
  "Staff will review the report and relationship. If the guardian name is missing or does not match, a video or phone review is required. You can explore teachers while waiting.": "कर्मचारी रिपोर्ट और रिश्ते की समीक्षा करेंगे। अभिभावक का नाम न होने या मेल न खाने पर वीडियो या फ़ोन समीक्षा होगी। इस बीच आप शिक्षक खोज सकते हैं।",
  "Relationship approved. Learning consent comes next.": "रिश्ता मंज़ूर है। अब पढ़ाई के डेटा की सहमति दें।",
  "Approval does not start tuition or share learning records. Continue guardian setup to review consent and create the named learner profile.": "मंज़ूरी से ट्यूशन शुरू नहीं होती और पढ़ाई के रिकॉर्ड साझा नहीं होते। सहमति की समीक्षा और दर्ज विद्यार्थी का प्रोफ़ाइल बनाने के लिए अभिभावक सेटअप जारी रखें।",
