  "No learners yet. Complete guardian onboarding to add a learner and their tuition needs.":
    "अभी कोई विद्यार्थी नहीं है। विद्यार्थी और ट्यूशन की ज़रूरत जोड़ने के लिए अभिभावक की शुरुआत पूरी करें।",
