  "Manage your application, private evidence and teaching schedule.":
    "आवेदन, निजी प्रमाण और पढ़ाने का समय सँभालें।",
  "Manage teaching schedule": "पढ़ाने का समय सँभालें",
  "Open teacher dashboard": "शिक्षक डैशबोर्ड खोलें",
