    "विषय, पाठ्यक्रम या कोर्स अलग हो तो अलग शिक्षण क्षेत्र बनाएँ। हर विषय क्षेत्र की सभी चुनी कक्षाओं, स्तरों या वर्षों पर लागू है। सभी घोषणाओं की जाँच चाहिए।",
