  "Arrangement closed.": "व्यवस्था बंद है।",
  "Complete every field, use a ₹500–₹20,000 budget and valid nonoverlapping weekly times.":
    "हर फ़ील्ड पूरा करें, ₹500–₹20,000 बजट और मान्य बिना टकराव वाले साप्ताहिक समय दें।",
