  "Guardian manages learning": "अभिभावक पढ़ाई के निर्णय लेते हैं",
  "Your guardian sends enquiries, chooses teachers and manages tuition decisions. You can follow your own progress.": "आपके अभिभावक अनुरोध भेजते हैं, शिक्षक चुनते हैं और ट्यूशन के निर्णय लेते हैं। आप अपनी प्रगति देख सकते हैं।",
  "We manage learning together": "हम दोनों मिलकर पढ़ाई सँभालते हैं",
  "Both of you can send enquiries, choose teachers and manage tuition decisions. Your guardian can change this permission.": "आप दोनों अनुरोध भेज सकते हैं, शिक्षक चुन सकते हैं और ट्यूशन के निर्णय ले सकते हैं। यह अनुमति अभिभावक बदल सकते हैं।",
  "Student leads; guardian stays involved": "विद्यार्थी आगे बढ़ता है; अभिभावक साथ रहते हैं",
  "You take the lead in choosing teachers. Your guardian can follow progress, step in and change this permission.": "शिक्षक चुनने में आप पहल करते हैं। अभिभावक प्रगति देख सकते हैं, मदद कर सकते हैं और यह अनुमति बदल सकते हैं।",
  "LEARNING TOGETHER": "मिलकर सीखें",
  "Who manages learning?": "पढ़ाई के निर्णय कौन लेता है?",
  "A clear choice for your family. Learning decisions stay separate from consent, account access and financial commitments.": "आपके परिवार के लिए एक स्पष्ट विकल्प। पढ़ाई के निर्णय, सहमति, खाते की पहुँच और पैसों की जिम्मेदारी से अलग हैं।",
  "Your learner profiles could not be loaded. Private details are hidden.": "विद्यार्थियों की प्रोफ़ाइल लोड नहीं हुईं। निजी जानकारी छिपा दी गई है।",
  "No learner profiles are available yet.": "अभी कोई विद्यार्थी प्रोफ़ाइल उपलब्ध नहीं है।",
  "Review learner profiles": "विद्यार्थी प्रोफ़ाइल देखें",
  "Learner history pages": "विद्यार्थी इतिहास के पृष्ठ",
  "Previous": "पिछला",
  "Next": "अगला",
  "This learner is unavailable on the current page. Choose an available learner or reload the first page.": "यह विद्यार्थी इस पृष्ठ पर उपलब्ध नहीं है। कोई उपलब्ध विद्यार्थी चुनें या पहला पृष्ठ फिर लोड करें।",
  "Loading learning permissions…": "पढ़ाई की अनुमतियाँ लोड हो रही हैं…",
  "Current learning permissions could not be loaded. Private details are hidden.": "पढ़ाई की मौजूदा अनुमतियाँ लोड नहीं हुईं। निजी जानकारी छिपा दी गई है।",
  "Reload learning permissions": "पढ़ाई की अनुमतियाँ फिर लोड करें",
  "CURRENT FAMILY CHOICE": "परिवार का मौजूदा विकल्प",
  "Under 15, guardian guidance can help with learning decisions. Age or class alone does not grant adult account rights. Guardian authorization and learning-data consent remain separate.": "15 साल से कम उम्र में अभिभावक का मार्गदर्शन पढ़ाई के निर्णयों में मदद कर सकता है। केवल उम्र या कक्षा से वयस्क खाते के अधिकार नहीं मिलते। अभिभावक की अनुमति और पढ़ाई के डेटा की सहमति अलग रहती हैं।",
  "Only the guardian can change this permission, manage consent or confirm a financial commitment. A student can still ask their guardian to decide for one enquiry.": "केवल अभिभावक यह अनुमति बदल सकते हैं, सहमति सँभाल सकते हैं या पैसों की जिम्मेदारी स्वीकार कर सकते हैं। विद्यार्थी किसी एक अनुरोध का निर्णय अभिभावक से लेने को कह सकता है।",
  "Review management choice": "पढ़ाई के प्रबंधन का विकल्प देखें",
  "Learning management saved. The student will see this choice.": "पढ़ाई का प्रबंधन सहेजा गया। विद्यार्थी को यह विकल्प दिखेगा।",
  "Review the permission change": "अनुमति में बदलाव की समीक्षा करें",
  "Choose how you manage learning": "तय करें कि पढ़ाई के निर्णय कैसे लेंगे",
  "Learning management": "पढ़ाई का प्रबंधन",
  "This changes who can make new learning decisions. Existing teacher choices and records remain. Guardian-only mode also blocks saved student retries; it does not cancel an arrangement or change consent.": "इससे तय होता है कि पढ़ाई के नए निर्णय कौन ले सकता है। मौजूदा शिक्षक चयन और रिकॉर्ड बने रहेंगे। केवल अभिभावक वाले विकल्प में विद्यार्थी के सहेजे पुराने अनुरोध भी दोबारा नहीं चलेंगे; इससे व्यवस्था रद्द नहीं होती और सहमति नहीं बदलती।",
  "I reviewed this permission and how it affects the student's learning decisions.": "मैंने इस अनुमति और विद्यार्थी के पढ़ाई संबंधी निर्णयों पर इसके असर की समीक्षा कर ली है।",
  "Confirm management choice": "प्रबंधन के विकल्प की पुष्टि करें",
  "Discard changes": "बदलाव छोड़ दें",
  "Open my teacher choices": "मेरे शिक्षक चयन खोलें",
  "Retry the same decision": "उसी निर्णय को फिर भेजें",
  "YOUR LEARNING, YOUR NEXT STEP": "आपकी पढ़ाई, आपका अगला कदम",
  "My teacher choices": "मेरे शिक्षक चयन",
  "Choose a teacher for each subject, follow replies and keep your guardian involved when you want help.": "हर विषय के लिए शिक्षक चुनें, उनके जवाब देखें और मदद चाहिए तो अभिभावक को साथ रखें।",
  "Review who manages learning": "देखें कि पढ़ाई के निर्णय कौन लेता है",
