  "Learning consent, account access and financial commencement remain with your guardian.": "पढ़ाई की सहमति, खाते की पहुँच और पैसों की जिम्मेदारी शुरू होने की पुष्टि अभिभावक के पास रहती है।",
  "Your guardian currently makes learning decisions. You can explore teachers and follow your enquiries here.": "अभी आपके अभिभावक पढ़ाई के निर्णय लेते हैं। आप शिक्षक देख सकते हैं और अपने अनुरोधों की प्रगति यहाँ देख सकते हैं।",
