  "Choose an enquiry": "कोई अनुरोध चुनें",
  "No enquiries yet. Start with one subject and a teacher who fits.": "अभी कोई अनुरोध नहीं है। एक विषय और उपयुक्त शिक्षक से शुरुआत करें।",
  "Enquiry history pages": "अनुरोध इतिहास के पृष्ठ",
  "This enquiry is unavailable on the current page.": "यह अनुरोध इस पृष्ठ पर उपलब्ध नहीं है।",
