  "Choose a subject": "कोई विषय चुनें",
  "Monthly budget (INR)": "मासिक बजट (रुपये)",
  "Learning format": "पढ़ाई का तरीका",
  "City or area": "शहर या इलाका",
  "Weekly learning preferences": "साप्ताहिक पढ़ाई के पसंदीदा समय",
  "This saves an enquiry for your existing education profile. It does not book a class, charge you or authorize financial commencement.": "इससे आपकी मौजूदा शिक्षा प्रोफ़ाइल के लिए अनुरोध सहेजा जाएगा। कोई कक्षा बुक नहीं होगी, पैसे नहीं कटेंगे और पैसों की जिम्मेदारी शुरू करने की अनुमति नहीं मिलेगी।",
  "I reviewed these learning criteria and want to send this enquiry.": "मैंने पढ़ाई की इन जरूरतों की समीक्षा कर ली है और यह अनुरोध भेजना चाहता हूँ।",
