  "Ask guardian to decide": "अभिभावक से निर्णय लेने को कहें",
  "I reviewed who will make this enquiry's learning decisions.": "मैंने समीक्षा कर ली है कि इस अनुरोध के पढ़ाई संबंधी निर्णय कौन लेगा।",
  "Enquiry decision preference saved.": "अनुरोध के निर्णय का विकल्प सहेजा गया।",
  "Confirm enquiry preference": "अनुरोध के विकल्प की पुष्टि करें",
  "Arrangement permissions could not be loaded. Private details are hidden.": "व्यवस्था की अनुमतियाँ लोड नहीं हुईं। निजी जानकारी छिपा दी गई है।",
  "Reload arrangement permissions": "व्यवस्था की अनुमतियाँ फिर लोड करें",
  "Your learning arrangement": "आपकी पढ़ाई की व्यवस्था",
  "Accepting learning terms confirms your teacher choice. Your guardian separately confirms any financial commencement and minimum tuition.": "पढ़ाई की शर्तें स्वीकार करने से आपके शिक्षक चयन की पुष्टि होती है। पैसों की जिम्मेदारी शुरू होने और न्यूनतम ट्यूशन शुल्क की पुष्टि अभिभावक अलग से करते हैं।",
  "Both sides accepted the learning terms.": "दोनों पक्षों ने पढ़ाई की शर्तें स्वीकार कर ली हैं।",
  "Your learning terms are accepted; waiting for the teacher.": "आपकी पढ़ाई की शर्तें स्वीकार हो गई हैं; शिक्षक की पुष्टि का इंतजार है।",
  "Review your learning terms before accepting.": "स्वीकार करने से पहले अपनी पढ़ाई की शर्तें देखें।",
  "Review learning terms": "पढ़ाई की शर्तें देखें",
  "I reviewed the monthly tuition and agree to these learning terms. Financial commencement remains separate.": "मैंने मासिक ट्यूशन शुल्क की समीक्षा कर ली है और पढ़ाई की इन शर्तों से सहमत हूँ। पैसों की जिम्मेदारी शुरू होने की पुष्टि अलग रहेगी।",
  "Learning terms accepted. Financial commencement is still separate.": "पढ़ाई की शर्तें स्वीकार हो गई हैं। पैसों की जिम्मेदारी शुरू होने की पुष्टि अभी अलग है।",
  "Accept learning terms": "पढ़ाई की शर्तें स्वीकार करें",
  "Help or replacement for this arrangement": "इस व्यवस्था के लिए मदद या शिक्षक बदलाव",
  "Your guardian chooses who manages learning. Check your current permissions to see whether you, your guardian or both of you can choose teachers.": "पढ़ाई के निर्णय कौन लेगा, यह आपके अभिभावक तय करते हैं। अपनी मौजूदा अनुमतियाँ देखकर जानें कि शिक्षक आप चुन सकते हैं, अभिभावक चुन सकते हैं या दोनों।",
  "Explore teachers and follow your search. Your guardian-selected management choice determines who makes learning decisions.": "शिक्षक खोजें और अपनी खोज की प्रगति देखें। अभिभावक का चुना प्रबंधन विकल्प तय करता है कि पढ़ाई के निर्णय कौन लेता है।",
  "Share your learner’s education, subject, availability and budget. We’ll review suitable teachers and prepare learning options for you.": "विद्यार्थी की शिक्षा, विषय, उपलब्ध समय और बजट बताएँ। हम उपयुक्त शिक्षकों की समीक्षा करके आपके लिए विकल्प तैयार करेंगे।",
  "This page requires the appropriate family account.": "इस पृष्ठ के लिए उपयुक्त पारिवारिक खाता चाहिए।",
  "Learner access is unavailable.": "विद्यार्थी की पहुँच अभी उपलब्ध नहीं है।",
  "Your guardian currently manages learning decisions.": "अभी आपके अभिभावक पढ़ाई के निर्णय लेते हैं।",
  "Enquiry access is unavailable.": "अनुरोध की पहुँच अभी उपलब्ध नहीं है।",
  "You asked your guardian to manage this enquiry.": "आपने इस अनुरोध का प्रबंधन अभिभावक से करने को कहा है।",
  "Learning management changed. Reload and review the current choice.": "पढ़ाई का प्रबंधन बदल गया है। मौजूदा विकल्प फिर लोड करके देखें।",
  "This enquiry changed or is closed.": "यह अनुरोध बदल गया है या बंद है।",
