  "Your guardian confirms financial commencement.": "पैसों की जिम्मेदारी शुरू होने की पुष्टि आपके अभिभावक करते हैं।",
  "Name corrections require guardian privacy review.": "नाम में सुधार के लिए अभिभावक की गोपनीयता समीक्षा चाहिए।",
