  "Arrangement access is unavailable.": "व्यवस्था की पहुँच अभी उपलब्ध नहीं है।",
  "· Family": "· परिवार",
  "Family learning terms": "परिवार की पढ़ाई की शर्तें",
  "Family acceptance": "परिवार की स्वीकृति",
  "Your response is recorded. The family reviews their choice and opens hiring terms. Check Teaching arrangements to review and confirm any shared terms.": "आपका जवाब दर्ज हो गया है। परिवार अपना विकल्प देखकर शर्तों की समीक्षा शुरू करता है। साझा शर्तें देखने और स्वीकार करने के लिए शिक्षण व्यवस्थाएँ खोलें।",
  "Review your current learning permissions and open your teacher choices.": "अपनी मौजूदा पढ़ाई की अनुमतियाँ देखें और शिक्षक चयन खोलें।",
  "The permitted family decision maker and teacher review and confirm the learning terms.": "परिवार का अधिकृत सदस्य और शिक्षक पढ़ाई की शर्तें देखकर उनकी पुष्टि करते हैं।",
  "Your guardian manages this enquiry": "इस अनुरोध का प्रबंधन आपके अभिभावक करते हैं",
  "Clear terms, shared confidence": "स्पष्ट शर्तें, साझा भरोसा",
  "Minimum tuition": "न्यूनतम ट्यूशन फ़ीस",
  "See the agreed commitment, confirm when teaching began and keep a shared record of payments.": "सहमत जिम्मेदारी देखें, पढ़ाई शुरू होने की तारीख की पुष्टि करें और भुगतान का साझा रिकॉर्ड रखें।",
  "Choose a valid arrangement to review its minimum tuition.": "न्यूनतम ट्यूशन फ़ीस देखने के लिए सही व्यवस्था चुनें।",
