  "Agreed monthly tuition": "सहमत मासिक ट्यूशन फ़ीस",
  "Half a month of agreed tuition. An odd paise rounds upward.": "सहमत मासिक ट्यूशन फ़ीस की आधी राशि। विषम पैसे होने पर राशि अगले पूरे पैसे तक होगी।",
