  "This amount remains recorded after ordinary closure or replacement.": "सामान्य रूप से व्यवस्था बंद करने या शिक्षक बदलने के बाद भी यह राशि दर्ज रहती है।",
  "No minimum debt applies until both parties confirm commencement.": "जब तक दोनों पक्ष शुरुआत की पुष्टि नहीं करते, न्यूनतम फ़ीस का बकाया लागू नहीं होता।",
  "Teaching commencement": "पढ़ाई की शुरुआत",
