  "Review commencement": "शुरुआत की समीक्षा करें",
  "This arrangement is closed. No new commencement can be confirmed. Its recorded balance and support remain available.": "यह व्यवस्था बंद है। अब नई शुरुआत की पुष्टि नहीं हो सकती। दर्ज बकाया और सहायता उपलब्ध हैं।",
  "Both parties must accept the learning terms before confirming financial commencement.": "पैसों की जिम्मेदारी शुरू होने की पुष्टि से पहले दोनों पक्षों को पढ़ाई की शर्तें स्वीकार करनी होंगी।",
  "You can follow this record. The account owner and teacher make financial confirmations; learning permissions do not change that authority.": "आप यह रिकॉर्ड देख सकते हैं। पैसों से जुड़ी पुष्टि खाते के स्वामी और शिक्षक करते हैं; पढ़ाई की अनुमतियाँ यह अधिकार नहीं बदलतीं।",
