  "Assess the linked case and available evidence before changing the minimum. Any refund requires a separate reviewed process.": "न्यूनतम फ़ीस बदलने से पहले जुड़े मामले और उपलब्ध प्रमाण का आकलन करें। राशि वापसी के लिए अलग समीक्षा प्रक्रिया जरूरी है।",
