  "Financial decisions are paused. Use support.": "पैसों के निर्णय अभी रुके हैं। सहायता लें।",
  "This arrangement has no agreed minimum. No retroactive charge applies.": "इस व्यवस्था के लिए न्यूनतम फ़ीस तय नहीं है। पिछली अवधि के लिए कोई नया शुल्क नहीं लगेगा।",
  "Minimum tuition changed. Refresh before deciding.": "न्यूनतम ट्यूशन फ़ीस बदल गई है। निर्णय से पहले जानकारी ताज़ा करें।",
  "History cursor not found.": "इतिहास की यह सीमा उपलब्ध नहीं है।",
