  "Staff must assess the open safety or non-delivery issue before financial commencement.": "पैसों की जिम्मेदारी शुरू होने से पहले कर्मचारी को खुली सुरक्षा या पढ़ाई न मिलने की समस्या का आकलन करना होगा।",
  "Only your pending start confirmation can be withdrawn.": "सिर्फ अपनी लंबित शुरुआत की पुष्टि वापस ले सकते हैं।",
  "Review the proposed commencement date with the other party.": "दूसरे पक्ष के साथ प्रस्तावित शुरुआत की तारीख की समीक्षा करें।",
  "Teacher screening is not current. Use support.": "शिक्षक की जाँच अभी मान्य नहीं है। सहायता लें।",
  "Record only a payment toward this commenced minimum, on or after its start date.": "शुरू हो चुकी सहमत न्यूनतम फ़ीस के लिए सही सीमा में भुगतान दर्ज करें।",
  "That payment reference is already recorded.": "इस रसीद के नाम से भुगतान पहले ही दर्ज है।",
