  "Confirmed credits cannot exceed the original minimum.": "पुष्ट भुगतान समायोजन मूल न्यूनतम फ़ीस से अधिक नहीं हो सकते।",
  "A participant must open the exception request.": "विशेष आकलन का अनुरोध किसी संबंधित पक्ष को खोलना होगा।",
